import { Issuer, generators } from 'openid-client'
import open from 'open'
import { password as passwordInput } from '@inquirer/prompts'
import type { Logger } from '@servicenow/sdk-build-core'

const SDK_OAUTH_APP_CLIENT_ID = 'SDK_OAUTH_APP_CLIENT_ID'
const DEFAULT_SDK_OAUTH_APP_CLIENT_ID = '543e5655f77746a28228c6009a599dfb'

export const oAuthClient = async (host: string, redirect_uri?: string) => {
    const issuer = new Issuer({
        issuer: 'ServiceNow',
        authorization_endpoint: `${host}/oauth_auth.do`,
        token_endpoint: `${host}/oauth_token.do`,
    })
    const client = new issuer.Client({
        client_id: process.env[SDK_OAUTH_APP_CLIENT_ID] ?? DEFAULT_SDK_OAUTH_APP_CLIENT_ID,
        ...(redirect_uri && { redirect_uris: [redirect_uri] }),
        response_types: ['code'],
        token_endpoint_auth_method: 'none',
    })

    return client
}

export const initOAuthFlow = async (host: string, logger?: Logger) => {
    try {
        // generate a random state and code verifier
        const state = generators.state()
        const codeVerifier = generators.codeVerifier()
        const codeChallenge = generators.codeChallenge(codeVerifier)

        const redirectUri = '/sdk-oauth.do'
        const client = await oAuthClient(host, redirectUri)
        const authorizationUri = client.authorizationUrl({
            state,
            redirect_uri: redirectUri,
            code_challenge: codeChallenge,
            code_challenge_method: 'S256',
        })

        logger?.info(
            `Opening web browser to authenticate with ${host}, or visit ${authorizationUri} to continue OAuth...`
        )
        try {
            await open(authorizationUri)
        } catch (error) {
            logger?.warn(
                'Could not open the browser automatically. Please navigate to this URL to continue authentication (we will attempt to copy it to your clipboard automatically):'
            )
            logger?.info(authorizationUri)
            try {
                const { default: clipboard } = await import('clipboardy')
                clipboard.writeSync(authorizationUri)
            } catch (e) {
                //leaving empty. it's just nice if they get the clipboard but not necessary
            }
        }

        const authCode = await passwordInput({
            message: 'Copy the code from the browser and paste it here: ',
        })
        const tokenSet = await client.oauthCallback(
            redirectUri,
            { code: authCode, state },
            {
                code_verifier: codeVerifier,
                state,
                response_type: 'code',
            }
        )

        return tokenSet
    } catch (error: any) {
        logger?.error('Access Token Error', error)
        return
    }
}
